// The Worker entry (wrangler.jsonc "main"): every dashboard path gets the Vite shell straight from static assets;
// everything else — the public site, /auth, /onboarding, /api, the API and MCP hosts — goes to Next.js (OpenNext).
//
// The shell can't be a middleware rewrite here: OpenNext routes a rewrite through Next.js, which has no page at
// /_spa/index.html, so it 404'd. Serving it before Next also skips the middleware's Supabase session refresh — the
// shell's own client keeps the session fresh, and /api requests still get the refresh.
// @ts-ignore — generated by `opennextjs-cloudflare build` (absent until the first build, e.g. in CI type-checks)
import { default as handler } from "./.open-next/worker.js"
import { SHELL_HEADERS, activeAppHintCookie, wantsSpaShell } from "./lib/spa-shell"

interface Env {
  ASSETS: { fetch(input: Request | URL | string): Promise<Response> }
}

const worker = {
  async fetch(request: Request, env: Env, ctx: unknown): Promise<Response> {
    const url = new URL(request.url)
    if (!wantsSpaShell(request.method, url)) return handler.fetch(request, env, ctx)

    // "/_spa/" — the assets binding answers "/_spa/index.html" with a 307 to it.
    const shell = await env.ASSETS.fetch(new URL("/_spa/", url))
    const res = new Response(shell.body, { status: shell.status, headers: shell.headers })
    for (const [k, v] of Object.entries(SHELL_HEADERS)) res.headers.set(k, v)
    const cookie = activeAppHintCookie(request.headers.get("cookie"))
    if (cookie) res.headers.append("Set-Cookie", cookie)
    return res
  },
}

export default worker

// OpenNext's Durable Object classes must be exported from the entry Wrangler deploys.
// @ts-ignore — generated by `opennextjs-cloudflare build` (absent until the first build, e.g. in CI type-checks)
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js"
